/* @socom-skeleton body CanSeeRegion__Q23zdb7CCameraFUi */
namespace zdb {
bool CCamera::CanSeeRegion(u32 mask)
	{
		if (!mask)
			mask = 1;

		if (m_do_region_test && (m_SeeRegions & mask) != 0)
			return true;

		return false;
	}
}

